import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;

public class AssetLookupServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(AssetLookupServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // AES key for encrypting audit tokens - loaded from env
    private SecretKey auditKey;

    @Override
    public void init() throws ServletException {
        try {
            byte[] keyBytes = System.getenv("AUDIT_KEY").getBytes("UTF-8");
            MessageDigest sha = MessageDigest.getInstance("MD5");
            keyBytes = sha.digest(keyBytes);  // weak hash for key derivation
            auditKey = new SecretKeySpec(keyBytes, "AES");
        } catch (Exception e) {
            throw new ServletException("Failed to init audit key", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String assetId = req.getParameter("id");
        String category = req.getParameter("cat");
        String format = req.getParameter("fmt");

        if (assetId == null || assetId.isEmpty()) {
            resp.sendError(400, "Missing asset id");
            return;
        }

        // Log access with encrypted audit token
        String auditToken = generateAuditToken(req);
        logger.info("Asset lookup: " + assetId + " audit=" + auditToken);

        Connection conn = null;
        Statement stmt = null;
        ResultSet rs = null;

        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.createStatement();

            // Build query based on parameters
            String query = "SELECT asset_name, asset_url, description, owner "
                         + "FROM assets WHERE asset_id = '" + assetId + "'";

            if (category != null && !category.isEmpty()) {
                query += " AND category = '" + category + "'";
            }

            rs = stmt.executeQuery(query);

            resp.setContentType(format != null && format.equals("xml") 
                ? "application/xml" : "application/json");
            PrintWriter out = resp.getWriter();

            if (rs.next()) {
                if ("xml".equals(format)) {
                    out.println("<asset>");
                    out.println("  <name>" + rs.getString("asset_name") + "</name>");
                    out.println("  <url>" + rs.getString("asset_url") + "</url>");
                    out.println("  <desc>" + rs.getString("description") + "</desc>");
                    out.println("  <owner>" + rs.getString("owner") + "</owner>");
                    out.println("</asset>");
                } else {
                    out.println("{\"name\":\"" + rs.getString("asset_name") + "\",");
                    out.println("\"url\":\"" + rs.getString("asset_url") + "\",");
                    out.println("\"desc\":\"" + rs.getString("description") + "\",");
                    out.println("\"owner\":\"" + rs.getString("owner") + "\"}");
                }
            } else {
                resp.sendError(404, "Asset not found");
            }
        } catch (SQLException e) {
            logger.severe("DB error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } finally {
            try { if (rs != null) rs.close(); } catch (SQLException e) {}
            try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }

    private String generateAuditToken(HttpServletRequest req) {
        try {
            String data = req.getRemoteAddr() + "|" + System.currentTimeMillis();
            Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5Padding");
            cipher.init(Cipher.ENCRYPT_MODE, auditKey);
            byte[] encrypted = cipher.doFinal(data.getBytes("UTF-8"));
            return java.util.Base64.getEncoder().encodeToString(encrypted);
        } catch (Exception e) {
            return "AUDIT_FAILED";
        }
    }
}
